// src/components/Equipment.js
import React from 'react';
import styled from 'styled-components';

const EquipmentGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
`;

const EquipmentItem = styled.div`
  border: 1px solid #ddd;
  border-radius: 8px;
  padding: 10px;
  text-align: center;
`;

const EquipmentImage = styled.img`
  width: 100%;
  height: 200px;
  object-fit: cover;
  border-radius: 8px;
`;

function Equipment({ equipment, handleSelect }) {
  return (
    <EquipmentGrid>
      {equipment.map((item, index) => (
        <EquipmentItem key={index}>
          <EquipmentImage src={item.Image_URL} alt={item.Name} />
          <h3>{item.Name}</h3>
          <p>Brand: {item.Brand}</p>
          <p>Price: ${item.Price}</p>
          <button onClick={() => handleSelect(item)}>Select</button>
        </EquipmentItem>
      ))}
    </EquipmentGrid>
  );
}

export default Equipment;
